using System;
using System.Collections.Generic;
using UnityEngine;

namespace Homesteader.Modding
{
    /// <summary>
    /// Runtime prefab lookup for modded assets.
    ///
    /// The mod's own files (including the prefabs generated by the Editor step
    /// Tools > Homesteader > Mods > Generate Mod Prefabs) are copied into the
    /// Unity project by tools/sync_mods_to_unity.py, so they live under a
    /// Resources folder hierarchy and can be loaded by path at runtime.
    ///
    /// Lookup strategy, in order:
    ///   1. A direct Resources path built from the key the resolver supplies
    ///      ("&lt;mod_id&gt;/prefabs/&lt;stem&gt;"), which is the layout the generator writes.
    ///   2. A prebuilt index, populated once, for anything that needs a name-only
    ///      match.
    ///
    /// This is deliberately not Addressables: the project does not have the
    /// Addressables package installed, and adding it would require a build-time
    /// catalogue step. Resources loading needs no extra package and no setup, at
    /// the cost of loading the whole Resources set into the build - which is a
    /// reasonable trade for a mod folder, and can be swapped later by injecting a
    /// different IPrefabProvider without touching the resolver.
    /// </summary>
    public sealed class ResourcesPrefabProvider : FileAssetResolver.IPrefabProvider
    {
        public const string ResourcesModsFolder = "Mods";

        private readonly Action<string> log;
        private Dictionary<string, GameObject> index;
        private readonly HashSet<string> misses = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        public ResourcesPrefabProvider(Action<string> log = null)
        {
            this.log = log;
        }

        public GameObject LoadPrefab(string key)
        {
            if (string.IsNullOrEmpty(key))
                return null;

            if (misses.Contains(key))
                return null;

            // 1. Direct path, matching what the generator writes.
            string normalized = key.Replace('\\', '/');
            string direct = $"{ResourcesModsFolder}/{normalized}";
            GameObject prefab = Resources.Load<GameObject>(direct);
            if (prefab != null)
                return prefab;

            // The generator writes "<mod>/prefabs/<stem>.prefab"; strip any
            // leading models/ or assets/ segment a caller may have included.
            string stem = System.IO.Path.GetFileNameWithoutExtension(normalized);
            foreach (string candidate in Candidates(normalized, stem))
            {
                prefab = Resources.Load<GameObject>(candidate);
                if (prefab != null)
                    return prefab;
            }

            // 2. Fall back to the name index (covers unusual layouts).
            EnsureIndex();
            if (index.TryGetValue(stem, out prefab) && prefab != null)
                return prefab;

            misses.Add(key);
            log?.Invoke($"[Mods] Prefab not found for '{key}'. " +
                        "Run Tools > Homesteader > Mods > Generate Mod Prefabs.");
            return null;
        }

        private static IEnumerable<string> Candidates(string normalized, string stem)
        {
            yield return $"{ResourcesModsFolder}/{stem}";
            yield return $"{ResourcesModsFolder}/{normalized}/prefabs/{stem}";
            yield return $"{ResourcesModsFolder}/{normalized}/models/{stem}";

            // "<mod_id>/prefabs/<stem>" is the common case.
            int slash = normalized.IndexOf('/');
            if (slash > 0)
            {
                string modId = normalized.Substring(0, slash);
                yield return $"{ResourcesModsFolder}/{modId}/prefabs/{stem}";
                yield return $"{ResourcesModsFolder}/{modId}/models/{stem}";
            }
        }

        /// <summary>
        /// Builds a stem -> prefab map once. Resources.LoadAll is the only runtime
        /// way to enumerate, so it is deferred until a path lookup has already
        /// failed, keeping the common case cheap.
        /// </summary>
        private void EnsureIndex()
        {
            if (index != null) return;

            index = new Dictionary<string, GameObject>(StringComparer.OrdinalIgnoreCase);

            GameObject[] all = Resources.LoadAll<GameObject>(ResourcesModsFolder);
            foreach (GameObject go in all)
            {
                if (go == null) continue;
                if (!index.ContainsKey(go.name))
                    index[go.name] = go;
            }

            if (all.Length > 0)
                log?.Invoke($"[Mods] Indexed {all.Length} mod prefab(s) from Resources/{ResourcesModsFolder}.");
        }
    }
}
